fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

fn sign(a: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len());
    for x in a {
        result.push(sign_of(x));
    }
    result
}

